#!/usr/bin/env node
// Builds supabase/functions/_shared/psi_<id>.generated.ts from a PSI markdown
// document (the Director-owned Source of Truth). The .md is the ONLY place the
// PSI text is edited (M-7); the generated module is what Deno can import.
//
//   node scripts/build-psi.mjs            -> (re)generate all
//   node scripts/build-psi.mjs --check    -> exit 1 if any generated file is stale (CI)
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const SOURCES = [
  { id: 'v80', md: 'IDSS_IBL_PSI_v8_final.md', exportName: 'PSI_V80_PROMPT' },
  // v9.0 DRAFT (DL-P13): used by the golden evaluation only. It goes to
  // production only after the Director approves its text.
  { id: 'v90', md: 'IDSS_IBL_PSI_v9.md', exportName: 'PSI_V90_PROMPT' },
  { id: 'v91', md: 'IDSS_IBL_PSI_v9_1.md', exportName: 'PSI_V91_PROMPT' },
];
const check = process.argv.includes('--check');
let stale = 0;

for (const s of SOURCES) {
  if (!existsSync(s.md)) continue;
  const raw = readFileSync(s.md, 'utf8');
  // The document is wrapped in a ``` fence for copy/paste use; strip it.
  const body = raw.replace(/^\s*```[^\n]*\n/, '').replace(/\n```\s*$/, '\n').trimEnd() + '\n';
  const sha = createHash('sha256').update(raw).digest('hex');
  const escaped = body.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');
  const out = `// GENERATED by scripts/build-psi.mjs from ${s.md} — DO NOT EDIT.\n` +
    `// Edit the .md (Director approval required, CONSTITUTION rule 1), then run\n` +
    `// \`node scripts/build-psi.mjs\`. CI runs it with --check.\n` +
    `// source-sha256: ${sha}\n\n` +
    `export const ${s.exportName}_SHA256 = "${sha}";\n` +
    `export const ${s.exportName} = \`${escaped}\`;\n`;
  const target = `supabase/functions/_shared/psi_${s.id}.generated.ts`;
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (check) {
    if (current !== out) { console.error(`[psi:check] STALE: ${target} does not match ${s.md}. Run: node scripts/build-psi.mjs`); stale++; }
    else console.log(`[psi:check] ok: ${target}`);
  } else {
    writeFileSync(target, out);
    console.log(`[build-psi] wrote ${target} (${body.length} chars, sha ${sha.slice(0, 12)})`);
  }
}
// DL-P30: the DE/EN template-line list of the production PSI (Module 3.10, DL-P29) as data for the
// language layer (src/lib/language/templateLines.ts). One source: the PSI .md (M-7).
{
  const md = readFileSync('IDSS_IBL_PSI_v9_1.md', 'utf8');
  const start = md.indexOf('TEMPLATE LINES IN GERMAN AND ENGLISH');
  if (start < 0) { console.error('[build-psi] template-line list not found in IDSS_IBL_PSI_v9_1.md'); process.exit(1); }
  const end = md.indexOf('\n---', start);
  const lines = md.slice(start, end < 0 ? undefined : end).split('\n');
  const pairs = [];
  for (let i = 0; i < lines.length; i++) {
    const bs = lines[i].match(/^BS: (.+)$/);
    const de = lines[i + 1]?.match(/^ {2}DE: (.+)$/);
    const en = lines[i + 2]?.match(/^ {2}EN: (.+)$/);
    if (bs && de && en) pairs.push([bs[1].trim(), de[1].trim(), en[1].trim()]);
  }
  // L-2 step 1 (DL-P32): the label table of Module 3.10 (BOSANSKI / DEUTSCH / ENGLISH columns)
  const tStart = md.indexOf('BOSANSKI                              DEUTSCH');
  const labels = [];
  if (tStart < 0) { console.error('[build-psi] label table of Module 3.10 not found'); process.exit(1); }
  for (const line of md.slice(tStart).split('\n').slice(2)) {
    if (!line.trim()) break;
    const cols = line.trim().split(/\s{2,}/);
    if (cols.length === 3) labels.push(cols);
  }
  const out = `// GENERATED by scripts/build-psi.mjs from IDSS_IBL_PSI_v9_1.md (Module 3.10, DL-P29) — DO NOT EDIT.\n` +
    `// [Bosnian template line, German line, English line]\n` +
    `export const TEMPLATE_LINES: readonly (readonly [string, string, string])[] = ${JSON.stringify(pairs, null, 1)};\n` +
    `// [Bosnian label, German label, English label] — the label table of Module 3.10 (DL-P32)\n` +
    `export const LABELS: readonly (readonly [string, string, string])[] = ${JSON.stringify(labels, null, 1)};\n`;
  const target = 'src/lib/language/templateLines.generated.ts';
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (check) {
    if (current !== out) { console.error(`[psi:check] STALE: ${target}. Run: node scripts/build-psi.mjs`); stale++; }
    else console.log(`[psi:check] ok: ${target}`);
  } else {
    writeFileSync(target, out);
    console.log(`[build-psi] wrote ${target} (${pairs.length} template lines)`);
  }
}
process.exit(stale ? 1 : 0);
